CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspaces (id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (workspace_id uuid REFERENCES workspaces(id), user_id uuid REFERENCES users(id), role text NOT NULL CHECK(role IN ('admin','creator','viewer')), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE invitations (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','creator','viewer')), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_at timestamptz, created_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE projects (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, description text NOT NULL DEFAULT '', created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE assets (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), project_id uuid, name text NOT NULL, media_type text NOT NULL CHECK(media_type IN ('image','video','audio','mask','layer','reference','timeline')), content_type text NOT NULL, storage_key text NOT NULL UNIQUE, sha256 text NOT NULL, bytes bigint NOT NULL CHECK(bytes>=0), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), parent_id uuid, UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id), FOREIGN KEY(workspace_id,parent_id) REFERENCES assets(workspace_id,id));
CREATE TABLE elements (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, kind text NOT NULL CHECK(kind IN ('character','product','environment','voice','style')), description text NOT NULL DEFAULT '', created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE TABLE element_assets (workspace_id uuid NOT NULL, element_id uuid NOT NULL, asset_id uuid NOT NULL, PRIMARY KEY(workspace_id,element_id,asset_id), FOREIGN KEY(workspace_id,element_id) REFERENCES elements(workspace_id,id), FOREIGN KEY(workspace_id,asset_id) REFERENCES assets(workspace_id,id));
CREATE TABLE storyboards (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), project_id uuid NOT NULL, name text NOT NULL, revision integer NOT NULL DEFAULT 1, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE TABLE shots (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, storyboard_id uuid NOT NULL, ordinal integer NOT NULL CHECK(ordinal>=0), prompt text NOT NULL DEFAULT '', duration_seconds double precision NOT NULL CHECK(duration_seconds>0 AND duration_seconds<=120), settings jsonb NOT NULL DEFAULT '{}', UNIQUE(workspace_id,id), UNIQUE(storyboard_id,ordinal), FOREIGN KEY(workspace_id,storyboard_id) REFERENCES storyboards(workspace_id,id));
CREATE TABLE shot_assets (workspace_id uuid NOT NULL, shot_id uuid NOT NULL, asset_id uuid NOT NULL, role text NOT NULL, PRIMARY KEY(workspace_id,shot_id,role), FOREIGN KEY(workspace_id,shot_id) REFERENCES shots(workspace_id,id), FOREIGN KEY(workspace_id,asset_id) REFERENCES assets(workspace_id,id));
CREATE TABLE workflow_revisions (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), capability_id text NOT NULL, version text NOT NULL, sha256 text NOT NULL, manifest jsonb NOT NULL, graph jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(workspace_id,capability_id,sha256));
CREATE TABLE workers (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, origin text NOT NULL, api_prefix text NOT NULL DEFAULT '/api' CHECK(api_prefix IN ('','/api')), enabled boolean NOT NULL DEFAULT true, inventory jsonb, checked_at timestamptz, UNIQUE(workspace_id,id), UNIQUE(origin));
CREATE TABLE provider_connections (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), provider_id text NOT NULL, encrypted_secret text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,provider_id));
CREATE TABLE runs (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), project_id uuid NOT NULL, worker_id uuid, workflow_revision_id uuid, created_by uuid NOT NULL REFERENCES users(id), capability_id text NOT NULL, capability_version text NOT NULL, route_id text NOT NULL, state text NOT NULL CHECK(state IN ('pending','submitting','submission_unknown','queued','running','succeeded','failed','cancel_requested','canceled')), invocation jsonb NOT NULL, graph jsonb, remote_id text, request_hash text NOT NULL, idempotency_key text NOT NULL, error text, output_ids jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id), UNIQUE(workspace_id,idempotency_key), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id), FOREIGN KEY(workspace_id,worker_id) REFERENCES workers(workspace_id,id), FOREIGN KEY(workspace_id,workflow_revision_id) REFERENCES workflow_revisions(workspace_id,id));
CREATE TABLE run_inputs (workspace_id uuid NOT NULL, run_id uuid NOT NULL, asset_id uuid NOT NULL, role text NOT NULL, PRIMARY KEY(workspace_id,run_id,role), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id), FOREIGN KEY(workspace_id,asset_id) REFERENCES assets(workspace_id,id));
CREATE TABLE run_steps (id uuid PRIMARY KEY, workspace_id uuid NOT NULL, run_id uuid NOT NULL, name text NOT NULL, state text NOT NULL, details jsonb NOT NULL DEFAULT '{}', FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id));
CREATE TABLE run_events (seq bigserial PRIMARY KEY, workspace_id uuid NOT NULL, run_id uuid NOT NULL, state text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(workspace_id,run_id) REFERENCES runs(workspace_id,id));
CREATE TABLE imports (workspace_id uuid NOT NULL REFERENCES workspaces(id), source_id text NOT NULL, payload_hash text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,source_id));
CREATE TABLE legacy_project_members (workspace_id uuid NOT NULL, project_id uuid NOT NULL, prompt_id text NOT NULL, source_scope text NOT NULL, PRIMARY KEY(workspace_id,project_id,prompt_id,source_scope), FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE INDEX runs_recovery ON runs(state,updated_at);
CREATE INDEX assets_workspace ON assets(workspace_id,created_at);
CREATE INDEX run_events_workspace ON run_events(workspace_id,seq);
